<?php

declare(strict_types=1);

/** @var array<string, mixed> $solicitud */
$value = static fn (string $key): string => e((string) ($solicitud[$key] ?? ''));
$state = trim((string) ($solicitud['estado'] ?? '')) ?: 'RECIBIDA';
$stateLabel = mb_strtoupper($state, 'UTF-8');
$history = is_array($authorizationHistory ?? null) ? $authorizationHistory : [];
$latestAuthorization = $history !== [] ? $history[count($history) - 1] : null;
$hasProduct = ($solicitud['producto_id_externo'] ?? null) !== null || ($solicitud['producto_codigo'] ?? null) !== null;
$matchScore = $solicitud['match_score'] ?? null;
$matchLabel = $matchScore !== null && $matchScore !== '' ? (string) $matchScore . '%' : 'Sin dato';
?>
