<section class="page-heading page-heading--dashboard request-detail__heading" aria-labelledby="request-title">
    <div class="page-heading__eyebrow"><p class="page-heading__path"><a href="/app#centro-notificaciones">Centro de notificaciones</a> <span aria-hidden="true">/</span> Solicitud</p><span class="status-label"><span aria-hidden="true"></span><?= e($stateLabel) ?></span></div>
    <h1 id="request-title">Solicitud de cotización</h1>
    <p class="request-detail__folio"><strong><?= $value('folio') ?></strong><span><?= $value('created_at') ?></span></p>
